class Customer {
  + name : string
  + surname : string
  + email : string
  + telephone : string
  + address : string
}

class Dish {
  + name : string
  + preparationTime : int
}

class Order {
  + totalCost : float
  + estimatedDeliveryTime : datetime
  + status : string
}

Customer "1" -- "*" Order : places
Order "*" -- "1..*" Dish : contains

@enduml

